import{_ as e,o,c as l,ak as t}from"./chunks/framework.DKi5cyCJ.js";const R=JSON.parse('{"title":"中断与抢占","description":"抢占优先级、子优先级、晚到、咬尾、PRIMASK 与 BASEPRI","frontmatter":{"title":"中断与抢占","description":"抢占优先级、子优先级、晚到、咬尾、PRIMASK 与 BASEPRI","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-中断与抢占.md","filePath":"pages/blog/2026-10-20-中断与抢占.md"}'),s={name:"pages/blog/2026-10-20-中断与抢占.md"};function d(r,a,i,p,c,_){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="中断与抢占" tabindex="-1">中断与抢占 <a class="header-anchor" href="#中断与抢占" aria-label="Permalink to &quot;中断与抢占&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>NVIC 里数值越小优先级越高。正在执行的中断，只能被抢占优先级更高的异常打断。抢占优先级相同的中断只挂起，当前函数返回后再运行。</p><p>进入异常时硬件压栈 R0、R1、R2、R3、R12、LR、PC、xPSR。外设中断线多数是电平触发，返回前要清外设标志。只清 NVIC 挂起位，返回后会立刻再进。函数名和启动文件不一致时，链接的是默认死循环。</p><h2 id="优先级分组" tabindex="-1">优先级分组 <a class="header-anchor" href="#优先级分组" aria-label="Permalink to &quot;优先级分组&quot;">​</a></h2><p>STM32 只实现优先级寄存器的高 4 位，软件里能用的是 0–15。用 HAL 或 CMSIS 设置，不要把 1 写进寄存器的 bit0。</p><p>HAL 的 <code>NVIC_PRIORITYGROUP_4</code> 表示这 4 位全是抢占优先级。<code>NVIC_PRIORITYGROUP_0</code> 表示没有抢占位，中断不能互相打断。复位后的分组效果和 GROUP_4 一样，<code>HAL_Init</code> 也会设成 GROUP_4。</p><p>子优先级只在多个挂起中断同时可以开始时排序，不能打断已经在执行的同级中断。</p><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">主循环</div><div class="blog-flow-arrow">被抢占</div><div class="blog-flow-node">TIM2<br><small>优先级 2</small></div><div class="blog-flow-arrow">被抢占</div><div class="blog-flow-node accent">USART<br><small>优先级 0</small></div></div></div><p>晚到：低优先级正在压栈时来了更高优先级，CPU 先执行更高的那个。咬尾：函数返回时已经有挂起中断，硬件跳过“出栈再压栈”，直接取下一个向量。</p><p>PRIMASK 关掉全部可配置中断，NMI 和 HardFault 仍会进入。BASEPRI 只挡住数值大于等于阈值的中断，更高优先级的控制环还能进来。FreeRTOS 用的是 BASEPRI：高于 syscall 上限的中断里不能调用内核 API。</p><p>临界区只包住几条赋值。关着总中断去等另一个中断来清标志，会变成死循环。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',13)])])}const P=e(s,[["render",d]]);export{R as __pageData,P as default};
